using EduVerse.Core.Common;

namespace EduVerse.Core.Curriculum;

/// <summary>
/// Built-in subject that works without any AI: fractions, from the meaning of a fraction to multiplying them.
/// Its exercises are generated in code (<see cref="Learning.FractionExercises"/>), each wrong option tagged with the misconception it reveals.
/// Other subjects are generated by the AI from any topic.
/// </summary>
public static class BuiltInSubjects
{
    public const string FractionsKey = "fractions";

    public static readonly string[] FractionConcepts = ["meaning", "equivalent", "simplify", "compare", "add-same", "add-different", "multiply"];

    public static Subject Fractions(TeachLanguage l)
    {
        string T(string en, string es, string fr, string ca) => Lang.T(l, en, es, fr, ca);
        return new Subject(FractionsKey, T("Fractions", "Fracciones", "Les fractions", "Fraccions"), T("Mathematics", "Matemáticas", "Mathématiques", "Matemàtiques"),
        [
            new("meaning", T("What a fraction is", "Qué es una fracción", "Ce qu'est une fraction", "Què és una fracció"),
                T("A fraction counts equal parts of a whole: the denominator says into how many parts, the numerator how many we take.", "Una fracción cuenta partes iguales de un todo: el denominador dice en cuántas partes se divide, el numerador cuántas tomamos.", "Une fraction compte des parts égales d'un tout : le dénominateur dit en combien de parts, le numérateur combien on en prend.", "Una fracció compta parts iguals d'un tot: el denominador diu en quantes parts es divideix, el numerador quantes en prenem."), []),
            new("equivalent", T("Equivalent fractions", "Fracciones equivalentes", "Fractions équivalentes", "Fraccions equivalents"),
                T("Multiplying or dividing the numerator and the denominator by the same number gives the same quantity.", "Multiplicar o dividir el numerador y el denominador por el mismo número da la misma cantidad.", "Multiplier ou diviser le numérateur et le dénominateur par le même nombre donne la même quantité.", "Multiplicar o dividir el numerador i el denominador pel mateix nombre dona la mateixa quantitat."), ["meaning"]),
            new("simplify", T("Simplifying fractions", "Simplificar fracciones", "Simplifier une fraction", "Simplificar fraccions"),
                T("Divide the numerator and the denominator by their greatest common divisor.", "Se dividen el numerador y el denominador por su máximo común divisor.", "On divise le numérateur et le dénominateur par leur plus grand diviseur commun.", "Es divideixen el numerador i el denominador pel seu màxim comú divisor."), ["equivalent"]),
            new("compare", T("Comparing fractions", "Comparar fracciones", "Comparer des fractions", "Comparar fraccions"),
                T("Write both fractions with the same denominator, then compare the numerators.", "Se escriben las dos fracciones con el mismo denominador y se comparan los numeradores.", "On écrit les deux fractions avec le même dénominateur, puis on compare les numérateurs.", "S'escriuen les dues fraccions amb el mateix denominador i es comparen els numeradors."), ["equivalent"]),
            new("add-same", T("Adding fractions with the same denominator", "Sumar fracciones con el mismo denominador", "Additionner des fractions de même dénominateur", "Sumar fraccions amb el mateix denominador"),
                T("Add the numerators and keep the denominator: the size of the parts does not change.", "Se suman los numeradores y se mantiene el denominador: el tamaño de las partes no cambia.", "On additionne les numérateurs et on garde le dénominateur : la taille des parts ne change pas.", "Se sumen els numeradors i es manté el denominador: la mida de les parts no canvia."), ["meaning"]),
            new("add-different", T("Adding fractions with different denominators", "Sumar fracciones con distinto denominador", "Additionner des fractions de dénominateurs différents", "Sumar fraccions amb denominador diferent"),
                T("First find equivalent fractions with a common denominator, then add the numerators.", "Primero se buscan fracciones equivalentes con un denominador común y después se suman los numeradores.", "On cherche d'abord des fractions équivalentes de même dénominateur, puis on additionne les numérateurs.", "Primer es busquen fraccions equivalents amb un denominador comú i després se sumen els numeradors."), ["add-same", "equivalent"]),
            new("multiply", T("Multiplying fractions", "Multiplicar fracciones", "Multiplier des fractions", "Multiplicar fraccions"),
                T("Multiply the numerators together and the denominators together, then simplify.", "Se multiplican los numeradores entre sí y los denominadores entre sí, y se simplifica.", "On multiplie les numérateurs entre eux et les dénominateurs entre eux, puis on simplifie.", "Es multipliquen els numeradors entre si i els denominadors entre si, i se simplifica."), ["simplify"]),
        ], true);
    }
}
